import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷二十二","description":"周易经传集解 - 周易经传集解卷二十二","frontmatter":{"title":"周易经传集解卷二十二","description":"周易经传集解 - 周易经传集解卷二十二"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/023.md","filePath":"zh/classics/jingchuan-jijie/023.md"}'),r={name:"zh/classics/jingchuan-jijie/023.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷二十二",tabindex:"-1"},[n("周易经传集解卷二十二 "),e("a",{class:"header-anchor",href:"#周易经传集解卷二十二","aria-label":"Permalink to “周易经传集解卷二十二”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解卷二十二 ​宋林栗撰序：卦曰：「益而不已必决，故受之以夬。」「夬」者，决也。夬之成卦，益之变也。自益之夬，震变为乾，巽反为兑，一阴五阳而成也。夫所以为益者，损上而益下也。益而不已，则上九之兑乘乎九五之尊。兑，泽也，五，天位也。泽上于天，其势必决，故取二爻之象，以为一卦之体，然后泽上于天，著见于外，而夬之形成矣。昔夫子观欹器，喟然叹曰：「夫物乌有满而不覆者哉？」然则益之上九，求益而不已，是以决而去之。兑反居四，从天而下也。夬：扬于王庭，孚号有厉。告自邑，不利即戎，利有攸往。彖曰：「夬」，决也，刚决柔也。健而说，决而和。「扬于王庭」，柔乘五刚也。「孚号有厉」，其危乃光也。「告自邑，不利即戎」，所尚乃穷也。「利有攸往」，刚长乃终也。下乾上兑。成卦曰「夬」者，自初至三皆为乾，而四乃兑也。「乾」为天，「兑」为泽。「乾」者，阳之至尊；「兑」者，阴之至卑。莫高乎天，莫下乎泽。今而反之，泽上于天，未有不决者也。乾为金，「兑」亦为金。「兑」，泽中之金，有顽矿之气。而乾之为金，精明坚刚，柔粹者也。以顽矿之金而乘坚刚之利，未有不决者也。故曰：「夬，决也，刚决柔也。」五阳而决一阴，是以谓之「夬」也。阳自复、临、泰、壮、浸长而消阴，至夬而后决也。或曰：五阴消阳谓之「剥」，五阳消阴谓之「夬」，其义何也？曰：剥，剥也。「剥果」谓之「剥」，「剥庐」谓之「剥」，「山附于地」谓之「剥」。凡此者，皆物宜在上者也。剥而落之，是以谓之「剥」也。「夬」，决也。决水谓之「决」，决痈疽谓之「决」，泽上于天谓之「决」。凡此者，皆物宜在下者也。决而溃之，是以谓之「夬」也。故子曰：「健而说，决而和。」乾，健也；「兑」，说也。内健则不挫，外说则不争，健以为决，说以为和。君子之治小人也，顺其势而利导之，若决积水于千仞之上，功成而无后患者，「健而说，决而和」故也。「夬，扬于王庭，孚号有厉，告自邑，不利即戎，利有攸往。」何谓也？曰：九五，天位也，王者之象也。庭，外虚也。九五为王宫，故上六有王庭之象。扬，播也。上六为「巽」，「巽」为风，为号令，故有扬庭孚号之象。所以「扬于王庭」者，以五阳进而一阴乘之也。阳为君子，阴为小人，一小人而乘众君子，其义不可以不决也。小人一而君子众，其势则可以决之矣。是故「扬于王庭」，正明其罪而决之也。孚，信也。厉，危也。君子至众，小人至寡，虽曰可决，有危道焉。何则？上下无阳，则一阳者，众阴之所求也。上下无阴，则一阴者，众阳之所与也。今上六之阴，虽处至穷之势，然九五与之为比，九三与之为应，九四与之同体，其免于系累者，独初九、九二耳。初九、九二远于上六，虽欲决之，其势有所不及。彼三阳者，苟或阴为之主，其危不亦近乎？然「夬」之诸阳，皆体乾健之德，其肯系累于小人，而隳君子之朋哉？故曰「有厉」，曰「有戎」，曰「有凶」。「有」之为言，不必然之辞也。五阳相信而不忘于号令，知其危而戒之，斯有万全之势，而无一跌之虞矣。「邑」，内也。「戎」，外也。九二之「惕号告自邑」者也。九五之「夬」，「夬即戎」者也。夫以五阳而决一阴，有百胜而无一败，自常情观之，宜若无足忧者。然薰狐有凿城之嫌，灼蠹有焚木之虑。鸟兽之穷，犹能攫搏，而况于人乎？是故劳心以务外者，不若治内而外自平；穷兵以服远者，不若修近而远自至。舜舞干而苗格，文王修教而崇降，此「告自邑，不利即戎」之义也。然则「利有攸往」，何谓也？曰：兵法所谓「归师勿遏，围城必阙」者，岂将纵舍之而已乎？盖优游宽缓而取之耳。夫君子之心，未尝不欲天下皆君子也。不幸而小人在上，托附于至尊，而乘君子之隙，击之则惧于不胜，而反受其祸，舍之则小人不除，常在君侧，未有不害治者也。是以「夬」之君子，夙夜危惧，更相儆戒，常若寇至。苟吾党之志坚而不可动，则小人自当退听，革心易虑，化为君子矣。苟为不然，然后「扬于王庭」，决而去之，所以为「健而说，决而和，不利即戎，利有攸往」者也。故子曰：扬于王庭，柔乘五刚也；孚号有厉，有危乃光也；告自邑，不利即戎，所尚乃穷也。利有攸往，刚长乃终也。「其危」与否之九五「其亡」之义同。当「夬」之时，尚于刚决，苟专其所尚，能刚而不能柔，乃取穷之道也。小人虽不可不防，而君子之道不可以不长，是以「利有攸往」。由「夬」而为「乾」，则刚长之终也，可不务乎？象曰：泽上于天，「夬」，君子以施禄及下，居德则忌。「泽」者「兑」也。「天」者「乾」也。泽无在天上之理，而此象言之者，谓泽之气上蒸于天也。「泽蒸于天」，势无不决，必将降而为雨也。君子者，民之所望以为膏泽者也。既已得时得位，在王庭矣，又可吝其泽而不施乎？故用「夬」之象，施禄以及下，则自天而降，沛然无不被矣。然泽之为雨，天之施也；君子之及物，人主之德也。若居而有之，是贪天之功以为已力也。以兑而乘乾，以六而乘五，其能以久安乎？故曰：君子以施禄及下，居德则忌也。或曰：「需之象曰：云上于天，需。云者，坎也。坎为水，为雨。不曰雨，不曰水，而谓之云，不曰夬，而谓之需，何也？」曰：坎，流水也；兑，止水也。为其流也，故或为雨，或为云；为其止也，故为泽而已。云之在天，流行散徙，未必皆为雨也，是以谓之需也。泽之在天，有下而已，虽欲不雨，其可得乎？是以谓之夬也。所以然者，阴阳和而后雨，坎之从乾，皆阳也，是以云而未雨也。兑之从乾，则刚下柔上矣，膏泽之降，不亦宜乎？杂卦曰：「夬，决也，刚决柔也，君子道长，小人道忧也。」夬之为卦，以五刚一柔而成，其在六爻，以君子决小人为义。不曰「君子道长，小人道消」，而曰小人道忧者，此圣人之深旨也。杂卦六十二，皆一辞而已，盖有合两卦而言之者，独夬、姤疑于辞费。夬之四言，又系于杂卦之末，其辞非隐奥难晓，学者可以不问而知，故莫肯深考，以为偶然而已，可不惜哉！夫以五刚而决一柔，君子之道可谓长矣，而小人之道，其穷若此，能勿忧乎？我盛而长，则无意外之虑；彼穷而忧，则有先事之防。然则以五刚而决一柔，吾未知胜负之所在也。乐毅破齐，下七十余城，所未下者，莒、即墨二城耳。夫差破越，尽有其地，以甲楯五千栖之于会稽。然即墨终以破齐而复燕，会稽终以灭吴而霸越，是皆穷而忧者也。齐湣之败，夫差之亡，皆百胜而无忧者也，可不惧哉！是以圣人于「夬」之六爻，未尝不丁宁而儆戒之。初九有「不胜」之咎，九二有「莫夜」之戎，九三有「壮𬱓」之凶，九四有「无肤」之悔，九五有「苋陆」之咎，上六有「无号」之凶者，诚以我盛而长，彼穷而忧故也。是故「夬」之君子，不患其不刚，而患其不能柔也；不患其不健，而患其不能说也；不患其不决，而患其不能和也；不患其不往，而患其「即戎」也。是故「夬」之六爻，以刚居柔者，处「夬」之善者也；以刚居刚者，志于「夬」而已，圣人之所甚惧也。然初九最远于上六，不往则「无咎」矣；九三与上六为应，「遇雨」则「无咎」矣；九五切近于上六，「中行」则「无咎」矣。惟九二之「惕号」，九四之「次且」，乃为善也。或曰：杂卦之义既得闻矣，敢问系于诸卦之未亦有其说欤？曰：此彖之所谓「不利即戎，利有攸往」者也。「不利即戎」，故丁宁谆复，不以为烦。「利有攸往」，故系于诸卦之末，明其一变而遂为「乾」也。圣人之旨，可不究欤？初九：壮于前趾，往不胜，为咎。象曰：「不胜」而「往」，咎也。初九，「乾」也。以阳居刚而在下卦之下，上无其应，而承于九二，二亦「乾」也，故曰「壮于前趾」。趾所以行也，壮趾则欲行而已。「乾」，健也，刚亦健也。以刚居刚，以健济健，有进而已。圣人之所以戒之也，故曰：「往不胜为咎。」「夬」之诸爻，大率与「壮」相类，所以异者，「大壮」四阳，「夬」五阳耳。「大壮」之初九曰「壮于趾」者，以初在下，故谓之「趾」也。而又益以一阳，故「夬」之初九曰「壮于前趾」，明其势益强，则其志益锐也。然五阳之势，足以决一阴而无疑，所以朝夕儆戒而莫敢先动者，有所待焉。而初九处最远之地，居最下之位，以欲进之心，持必决之志，不量其力，不度其时，往而不胜，是自为其咎者也，非不幸也。庆历中，仁宗进用韩琦、杜衍、范仲淹、富弼在政府，欧阳修、余靖、王素、蔡襄为谏官，夏竦罗枢密使，鲁人石介作圣德颂，指言忠邪之辨。当此之时，可谓「夬」之世矣。然介卒以不克而斥死于远方，身没而几有斲棺之祸。自是朋党之论始兴，而君子小人迭为胜负矣。介之无成，非不幸也，自为之咎也。时韩、范二公自陜入觐，闻介此颂，叹曰：「天下事正坐此辈坏却。」若二公者，可谓中行之君子矣。故子曰：「不胜而往，咎也。」昔之观人者，观其邪正而不要其穷达；论事者，论其是非而不计其成败。夫岂以不胜而为其咎也哉？盖君子之举也，见可而进，知难而退。初九以必不胜之势，而侥幸于不可成之功，此其所以戒之也。九二：惕号，莫夜有戎，勿恤。象曰：「有戎勿恤」，得中道也。九二，「乾」也。以阳居柔而在下卦之中，上无其应，而承于九三，三亦「乾」也，故曰：「惕号，莫夜有戎，勿恤。」「惕」者，危惧之貌也；「号」，儆戒之辞也。「莫夜」者，人情懈怠之时，而事变不测之际也。「有戎」者，未必然之辞也；「勿恤」者，甚之之辞也。夫「乾」，天下之至健也，德行常易以知险。而九二居中，得刚柔之节，明得丧之理，故能忧惧而儆戒，以为莫夜之间，将有寇戎乘吾之隙，其可以「勿恤」乎？易以下卦为昼，上卦为夜，故九二之视九四，有「莫夜」之象，犹「乾」之「夕惕」也。三与上为应，四与上同体，则有戎之「恤」，不亦宜乎？故子曰：「有戎勿恤，得中道也。」九三，壮于𬱓，有凶。君子夬夬，独行遇雨，若濡，有愠，无咎。象曰：「君子夬夬」，终无咎也。九三下体为「乾」，上体亦为「乾」，以阳居刚而在下卦之上，应乎上六之「巽」，故曰：「壮于𬱓，有凶。」「𬱓」，颧骨也，壮之见于面者也。三以阳居刚而在下卦之上，故有「壮𬱓」之象。书曰：「尔无忿疾于顽。」语曰：「人而不仁，疾之已甚，乱也。」君子刚中而柔外，无怨而无恶，故能使小人革心而顺服。今九三与上六为应，而乃见其壮于颜面之间，则小人惧矣。小人惧，则将畜其忿戾以致毒于我，蜂虿有之，而况人乎？二之有凶，固其宜也。故曰：「君子夬夬，独行遇雨若濡，有愠，无咎。」「夬夬」也。「夬夬」者，决之又决也。为其一爻而有重「乾」之象，是以谓之「夬夬」也。「雨」，阴阳和也。诸阳莫应于上六，而九三独应之，又有乾「巽」之合，是以谓之「独行」而「遇雨」也。「独行」而「遇雨」，宜「若濡」矣。然君子上交不谄，下交不渎，磨而不磷，涅而不缁，虽「遇雨若濡」，而实未尝濡也。夫君子之与小人，如冰炭之不相入也。君子之欲去小人，犹小人之欲无君子也。故诗曰：「忧心悄悄，愠于群小。」今以五阳而决一阴，而九三之君子与之为应，其不濡者几希矣，则其同类之「愠」，不亦宜乎？然君子之势如此其盛，小人之党如彼其衰，而九三以重刚之体，怀「夬夬」之心，岂将舍此而从彼哉？将以释其忿戾之情而开其柔服之意，不得不如是耳。由是言之，「愠」之者过也，非九三之咎也。不忍于「遇雨」之「愠」，而宁受「壮𬱓」之「凶」，斯为咎矣。故子曰：「君子夬夬，终无咎也。」九四：臀无肤，其行次且。牵羊悔亡，闻言不信。象曰：「其行次且」，位不当也。「闻言不信」，聪不明也。九四下体为「乾」，上体为「兑」，以阳居柔，而在上卦之下，下无其应，而承于九五之「乾」，连于上六之「巽」，故曰「臀无肤，其行次且」。「臀」，体之末也。阳为宾，阴为虚。四与五、上同体，四、五皆阳，而上为阴，是四之「臀无肤」也。「臀无肤」而位不当，故「其行次且」。然处则不安，行则不进也。「夬」之五阳，惟二、四居柔，二远于上而近之，又与之同体，至于「次且其行」，则四之操心危而虑患深矣。故曰：「牵羊悔亡，闻言不信。」四体「兑」，「兑」为羊；上体「巽」，「巽」为绳，故有「牵羊」之象。「兑」为口舌，「巽」为不果，故有「闻言不信」之象。羊，很而喜触者也。以阳五而决一阴，有余力矣，何至于触藩而自羸其角也哉？为其同体而牵去其羊，斯无悔矣。「大壮」之「悔亡」，亦犹是也。四之「牵羊」也，岂徒然而已？将至诚恻怛而致其教戒焉，使其革心而为善也。君子又何求哉？然上六阴柔，闻其言而不能信，至于恶积而不可揜，罪大而不可解，然后「扬于王庭」，与众弃之，此小人之所以甘心于𫓧钺而无所归怨者也。故曰：健而说，决而和，九四之谓矣。故曰：「其行次且，位不当也；闻言不信，聪不明也。」九五：苋陆夬夬，中行无咎。象曰：「中行无咎」，中未光也。九五，「乾」也。以阳居刚而在上卦之中，下无其应，而承于上六之「巽」，故曰：「苋陆夬夬」。「苋陆」，草名，柔脆易折之物也。「乾」为金，「巽」为蕃鲜，故有「苋陆夬夬」之象。「夬夬」者，决之又决者也。以「苋陆」之柔折而拔之易耳，何至于决之又决乎？夫九五者，阳之至盛者也；上六者，阴之至穷者也。以至刚而决至柔，以至盛而决至衰，譬犹以精金利器决柔脆之草，决而不中，则或伤之己。荆山之玉，不以投鼠；隋侯之珠，不以弹雀。以九五之金，决上六之苋，何以异于是？唐太宗之征高丽，文宗之诛宦官是也。所以然者，为其不图万全之功，而侥幸于一战之胜，彖之所谓「不利即戎」者也。故曰：「中行无咎，中未光也。」夫极刚健而以中行之，宜其光明而不疚矣。今也用于「苋陆」，至于「夬夬」，仅能「无咎」而已，此其所以为「未光」者欤？子曰：「孚号有厉，其危乃光也。」则五之「即戎」未光宜矣。或曰：九三一爻而有重刚之象，是以著「夬夬」之辞。五之为「乾」，一而已，其系之「夬夬」，何也？曰：五，天位也。「乾」为天，是亦「重乾」之象矣。「飞龙在天」，亦犹是也。上六：无号，终有凶。象曰：「无号」之「凶」，终不可长也。上六，「巽」也。以阴居柔而在上卦之上，应乎九三而乘于九五，二爻皆「乾」也，故曰：「无号，终有凶。」号有二：有扬庭之号，有儆戒之号。「乾」为健，「巽」为号。人情常谨于始而怠于终，敬其大而忽其小，畏其所难而蔑其所易。阳之盛至于九五，阴之穷极于上六，则向之「惕号」者，有时而怠矣。故戒之曰：「无号，终有凶。」言儆戒之不可忘也。「夬」之诸爻，皆警戒之意。至于上六，「夬」之终也。小人之罪既已著明矣。苟无扬庭之号，以正其典刑，是又养寇而遗患者也。故曰：「无号，终有凶。」言事机之不可失也。桓彦范不杀武三思，以为杌上肉耳，此则无号之凶也。故子曰：「无号之凶，终不可长也。」一日之长，为姤、为遁，为剥、为否，凶之渐也。可畏哉！圣人之爱君子而忧小人至矣。序卦曰：「夬者，决也。决必有遇，故受之以姤。姤者，遇也。」姤之成卦，夬之反也。自夬之姤，乾反居上，兑反为巽，初上相易而成卦也。乾反居上，则刚长之极矣。兑反为巽，则柔服之甚矣。刚长之极，而柔伏之甚，此小人之所以遇君子也。夫阴阳相求，物之情也。刚柔相推，时之运也。穷于上，必反于下，决于此，遇于彼，自然之理也。阳之用事，极于季夏，一阴相遇而秋矣。是故夏秋之交，为阳盛而阴伏，是其所以遇之。然一阳为复，一阴为姤，终则复始，刚柔相遇则同也。阳谓之复，阴谓之姤，何也？曰：阳复于艮，万物归根复命之时也。阴遇于坤，万物著见之时也。乾之从巽，必出乎兑；巽之从乾，必出乎离，然后相遇于坤。坤者，申也，孟秋之月也，夫是以谓之姤也。若复之坤、震，则不相遇矣。坤，土也；艮，亦土也。艮反于土，动而成震，夫是以谓之复也。圣人内刚而外柔，内君子而外小人，以阳为主，阴为客，故阳来谓之「复」，而阴来谓之「姤」也。夫岂特圣人之心然哉？亦本于天地自然之理而已矣。姤：女壮，勿用取女。彖曰：「姤」，遇也，柔遇刚也。「勿用取女」，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义大矣哉！下巽上乾，成卦曰「姤」者，初为巽，自二以往皆为「乾」。乾，健也。上健而下巽，斯以为遇巽巽也乎？曰：未也。乾，西北也；巽，东南也。东南西北，横亘相直，是以谓之遇也。乾之从巽，必出乎兑；巽之从乾，必出乎离，然后相遇于坤。坤者，申也。阳之终，阴之始，相遇于未申之间，是以有天地相遇之象，而其卦为「姤」也。乾为金，巽为木，阳金阴水，相得而有合，是以谓之「遇」也。故子曰：「姤，遇也，柔遇刚也。」说者皆以一柔而遇五刚，斯谓之「姤」。愚谓一柔而遇五刚，争宠之道也，而何遇之云乎？谓夫一阴方来，始与阳遇，是以谓之「姤」也。「姤，女壮，勿用取女。」何谓也？曰：巽，长女也。卦唯一阴为主于内，五阳皆欲求之，壮甚也。姤之言遇也，诗云「邂逅相遇」是也。不待其配，遇人而合，不可取之女也。然而天地不相遇，则品物不章；君臣不相遇，则政化不行。所恶于遇者，非恶其合也，恶其长也。妇人之义，从一而终。使初六之遇九二，遂止而不往，则如「姤」之象，复何尤哉？为其一柔而五刚，既遇不已，又舍而之他，惟其所遇，刚不能制，是以不可取也。故子曰：「勿用取女，不可与长也」。天地相遇，品物咸章也；刚遇中正，天下大行也。刚虽遇柔，而不失其中正，则风行天下，无乎不被矣。故又赞之曰：「姤之时义大矣哉！」一阴之来，虽有消阳之渐，然遇之以中正，则顺伏而无违，教化之行，民用和睦。「姤」之时义，斯为大矣。说者以「刚遇中正」为二五之遇，是谓执文害辞，失所谓「柔遇刚」之义矣。象曰：天下有风，「姤」，后以施命诰四方。「天」者，「乾」也。「风」者，「巽」也。风也者，天之号令也。风行天下，其施命诰四方之象乎？是故「夬」之上九，「风行天上」，则曰「扬于王庭」；「姤」之初六，「风行天下」，则曰「后以施命诰四方」也。或曰：然则「风行天上」，其卦为小畜，何也？曰：「小畜」之「巽」在四，而九五乘之，是以为懿文德，密云而不雨也。「夬」之「巽」在上，而乘乎九五矣，虽欲畜之，其可得乎？是以谓「扬于王庭，施禄以及下」也。杂卦曰：「姤，遇也，柔遇刚也。」姤之为卦，以一柔五刚而成，其在六爻，以柔遇刚为义。夬彖既言之矣，杂卦又申言之，不几于赘乎？曰：彖也者，一卦之义也；杂也者，六爻之义也。彖与爻同，圣人不以强而别；爻与彖异，圣人不以苟而合。至于夬、姤之义，观其彖则见其爻，观其爻则知其彖，是以重复其辞，而不以为烦也。或曰：若是则一辞而足矣。既谓之遇，而又曰「柔遇刚也」，岂非赘与？曰：易之言遇多矣，有刚柔相遇者，同人之二五「师克相遇」是也。有以刚遇刚者，暌之初九「遇元夫」是也。有以柔遇柔者，小过之六二「遇其妣」、「遇其臣」是也。有以刚遇柔者，丰之初九「遇其配主」，九四「遇其夷主」是也。若曰遇而已矣，安知非二五之相遇乎？故曰：「姤，遇也，柔遇刚也。」岂是得已而不已哉？初六「系柅」而「贞吉」、九二「包鱼」而「无咎」者，以其遇之也。九三有「次且」之「厉」，九四有「无鱼」之凶，九五有「包瓜」之陨，上九有「上穷」之吝者，为其不遇而求之也。然姤之阳以刚居柔者，志在于遇；以刚居刚者，无意遇之矣。九三、九五，无意于求之遇，故为「次且」，为「含章」。九四、上九，志在于遇，故凶吝随之矣。此初六之辞所以兼言「有攸往见凶」者也。初六：系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅。象曰：「系于金柅」，柔道牵也。初六，「巽」也，以阴居刚，而在一卦之下，应乎九四而遇于九二，二爻皆「乾」也。故曰：「系于金柅，贞吉。」「柅」，或作「𪭧」，说者曰：「络丝跌也。」青齐谓之柅，以金为之，取其坚重也。「巽」为丝，为绳直，「兑」为金，故有「系于金柅」之象。治丝与绳者必以柅，柅轻则摇动而丝棼，柅重则端正而绳直，初六之于九二是也。五阳皆金，而独二为柅者，谓其居下而得中，承五金之聚也。聚五金以为一柅，其孰能动之哉？圣人以初六之柔，有牵系诸阳之渐，因其遇二也，遂为之戒焉，使之「系于金柅，柅不动，豕孚蹢躅」。初既与二为遇矣，又进而有所往，所见宜其凶也。自「姤」而往，其卦为「遁」，「遁」之初六亦曰「勿用有攸往」是也。或曰：初配在四，不使之从四，而使之系二乎？曰：此卦以遇为义，盖遇合之女，未尝择配也。二近而先，斯得之矣。又使之求配而合焉，则是与之长，而其遇不可胜穷也。初苟舍二，犹遇九三，然则四之求之，亦已远矣。「羸豕」，牝豕也。兽之淫者莫若豕，而牝为甚焉。左氏传所谓「娄猪」是也。孚，孳尾也。既孚而犹「蹢躅」，淫躁之甚也。初六既系于二，而求过不已，故有「羸豕孚蹢躅」之象焉。制之于早，则如「金柅」之不可移，纵而弗图，则蹢躅而难制矣。可不戒哉？故子曰：「系于金柅，柔道牵也。」或曰：坎为豕而巽象之，何哉？曰：初六之巽，有攸往，故曰巽往则为离，离坎配也，取诸牝豕，不亦宜乎？故曰：「有攸往，见凶。」见者，「离」也。九二：包有鱼，无咎，不利宾。象曰：「包有鱼」，义不及宾也。九二，「乾」也，以阳居柔而在下卦之中，上无其应，而遇于初六之「巽」，故「包有鱼」。「包」，罩也，罔罟之类也。诗曰：「烝然罩罩。」旧说以为包苴之包，或以为庖厨之庖，皆非也。初为「巽」，三为「兑」，故二有「离」象。「巽」为鱼，「离」为罔罟，以二乘初，有包罩之象。鸡豚狗彘，人之所畜，不可以言遇也。鱼在川泽，则有时而遇之矣。故「姤」之民以鱼为喻，犹屯之民以鹿为喻也。五阳而求一阴，是鱼至少而罔之者众也。二近而先，斯得之矣，故曰：「无咎，不利宾。」夫初于四为配，而二取之，宜若有咎矣。然二之所取者鱼也，非四之所得有也。若取四之鸡豚狗彘，得为无咎乎哉？二以四为宾，宾，外也，为其无臣主之分也。若九五「包鱼」而二取之，得为无咎乎哉？施罩以待鱼，志于得耳。遇而不取，以利于宾，义之所不及也。圣人惧五阳之争而一阴之长，故使九二「包鱼」而取之。初六「系于柅」而勿往，则无女壮之渐矣。遇而不取，以为九四之利，则其遇也，岂特四而已哉？故子曰：「包有鱼，义不及宾也。」君子之道，斯为中庸矣。九三：臀无肤，其行次且，厉，无大咎。象曰：「其行次且」，行未牵也。九三上体为「乾」，下体为「兑」，以阳居刚而在下卦之上，上无其应，而连于初六之「巽」，故曰：「臀无肤，其行次且。」三与初、二同体，二、三皆阳而初为阴，是三之「臀无肤」也。三以纯刚而与渐壮之阴同体，非其志也，是以「其行次且」也，故曰「厉，无大咎」。阴消二则及三，可谓「厉」矣。以其无意于遇，知危而自警，不与二争民，则可以「无大咎」矣。「姤」之九三即「夬」之九四也，其为「无肤」而「次且」则同也。「夬」之九四，牵羊则「悔亡」，今反为「姤」，而「兑」体犹存，是其未能牵之，是以「次且」如故也。故子曰：「其行次且，行未牵也。」九四：包无鱼，起凶。象曰：「无鱼」之「凶」，远民也。九四上体为「乾」，下体亦为「乾」，以阳居柔而在上卦之下，应乎初六之「巽」，故曰「包无鱼」。九四志于遇者也，初既与二遇矣，四又隔于九三，远不相及，是临渊而羡鱼者也，故曰「起凶」。包而「无鱼」，则亦已矣，何咎之有？起而争之，斯为凶矣。或曰：四失其配，起而争之，何遽凶乎？曰：「姤」者，遇合之女，未尝择配而从也。夫既遇之，而我以为配，是一民而二君矣，又能保其不往也哉？五阳固志以决一阴，犹不能决而反为「姤」矣。四远于初，二与之遇，而四复争之，是众君子内自相敌，几何而不为小人之所乘哉？此其所以「凶」也。故子曰：「无鱼之凶，远民也。」鲁昭公将去季民，宋乐祁曰：「无民而能逞其志者，未之有也。静以待民犹可，动必忧。」昭公卒不克而出，死于乾侯，「起凶」之证也。九五：以杞包瓜，含章，有陨自天。象曰：九五「含章」，中正也。「有陨自天」，志不舍命也。九五，「乾」也。以阳居刚，而在上卦之中，远无所应，近无所遇，而介于四上之间，二爻皆「乾」也。故曰：「以杞包瓜，含章，有陨自天。」「杞」，柳也，告子所谓「以杞柳为杯棬」者也。「瓜」，木瓜也，诗所谓「投我以木瓜」者也。「以杞包瓜」，孔子所谓「繋而不食」者也。「剥」之上九亦曰：「硕果不食。」瓜，木果之硕者。予尝询之圃人，春华而夏实，霜降而后熟，惧夫风雨虫兽之害，往往为𤱵掬包裹，繋于枝干之上，不然，无孑遗矣。「姤」一阴之长，至五为「剥」，百果草木至此而皆剥矣。然而累然硕果犹在其上，是必有以包之者也。以杞云者，言其包络之坚也。夫一阴虽微，志在于「剥」。九二则与之比，既为所系矣。九三则与之同体，亦已危矣。九四则与之为应，将起而争之矣。惟九五居中守正，无意于遇，不为初六小人之所染污，则是全德而不刓，含章以有待也。夫「包瓜」者，必于一阴之时，过此则惧其遂剥也。「含章」者，必于一柔之世，过此则六三将与之配，惧其遂消也。夫阴长而阳消，百果草木至剥而皆陨者，天之命也。以杞包瓜而免于陨者，人之志也。包终坚完而不免于陨者，亦天也。未尝包之，与包之不坚，则其势必至于陨，不可以言天也。若九五者，包乎二刚之间，远无所应，近无所遇，则其包之坚且完矣。其有陨者，可以归之天矣。故子曰：「九五含章，中正也。有陨自天，志不舍命也。包不包，人也；陨不陨，天也。不舍吾志而已，其如命何哉？」论语作「匏瓜」。匏瓜，苦瓠也。苦瓠人所不食，故繋之以供无舟而求济者耳。或曰：「以杞包瓜，则何从而陨乎？」曰：飘风暴雨，发屋拔木，是岂包繋之所能御哉？若此者，可以言命矣。故孟子有言：「知命者不立乎岩墙之下。」或曰：「然则夫子之言曰：吾岂匏瓜也哉？焉能繋而不食？何也？」曰：夫子论逸民七人，而曰：「我则异于是，无可无不可。」孟子亦曰：「可以仕则仕，可以止则止，孔子也。」故夫含章以待者，时则有之矣，而孔子不为也。乃孔子则欲拨乱世而反之正者也，其能如瓠瓜之不食乎？故曰：「不曰坚乎？磨而不磷；不曰白乎？涅而不缁。」是以南子不可见而见，公山佛肸不可往而欲往也。虽然，善学柳下惠者，莫若鲁男子。世之君子，苟欲不磷，则如勿磨；苟欲不缁，则如勿涅；苟欲不陨，则不若包繋之坚完也。若此，可谓善学孔子矣。上九：姤其角，吝，无咎。象曰：「姤其角」，上穷吝也。上九，「乾」也。以阳居柔而在一卦之上，无应无遇，而乘九五之「乾」，故曰「姤其角」。「角」，上穷也。一阴之长，至于上则为角。上九志在于遇，其所遇角矣。初六，「兑」之反，故有羊角之象焉。「乾」为君子，「兑」为小人，「兑」之象为羊，羊，阴狠而善触者也。故大壮与夬，皆以「牵羊」、「丧羊」为义。夬之初九将决上六，往而不胜，是以为姤。今姤之上九，乃求遇焉。小人之未得志也，巽其辞色以媚君子；及其既得志也，惟君子之务去，则上九之遇初六也，岂复遇其柔巽也哉？「姤其角」而已矣，故曰「吝，无咎」。吝，羞也。姤至上九，君子之道穷矣。穷而求遇，其羞吝也，自取之矣，又谁咎乎？故子曰：「姤其角，上穷吝也。」穷则变矣，变而为萃，羊角在上，不其然乎！周易经传集解卷二十二，",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
